explicit oo_frontend(config cfg)
    : m_cfg(cfg),
      m_tags(cfg.logical_sets * cfg.logical_ways),
      m_phys(cfg.physical_lines),
      m_slots(cfg.oo_pib_entries) {
  check_tag_hash_bankrow(cfg.tag_hash_bankrow,
                         cfg.selected_mode == mode::PAPER_OO,
                         cfg.finite_service, cfg.logical_sets, cfg.tag_banks);
  check_progressive_wakeup_mode(cfg.progressive_wakeup,
      static_cast<unsigned>(cfg.selected_mode), cfg.finite_service);
  assert(cfg.logical_sets && cfg.logical_ways && cfg.physical_lines);
  assert(cfg.allocation_width && cfg.oo_pib_entries);
  assert(cfg.ref_count_bits && cfg.ref_count_bits < 32);
  assert(cfg.tag_banks && cfg.tag_requests_per_bank_per_cycle &&
         cfg.tag_requests_per_cycle);
}

void begin_cycle(uint64_t cycle) {
  if (cycle == m_cycle) return;
  m_cycle = cycle;
  m_allocations_this_cycle = 0;
}

bool admit(uint64_t uid) {
  if (find_entry(uid)) return true;
  if (m_entries.size() >= m_cfg.oo_pib_entries) return false;

io_access_result access(uint64_t cycle, uint64_t uid, uint64_t address) {
  begin_cycle(cycle);
  entry *owner = find_entry(uid);
  assert(owner);
  const uint64_t line = address & ~(kLogicalLineBytes - 1);
  tag_entry *tag = find_tag(line);
  if (tag) {
    attach_reference(*owner, tag->physical);
    ++(m_phys[tag->physical.id].ready ? m_valid_hits : m_pending_hits);
    assert_shadow_refs();
    return {m_phys[tag->physical.id].ready ? io_access_kind::VALID_HIT
                                            : io_access_kind::PENDING_HIT,
            tag->physical};
  }
  if (m_allocations_this_cycle >= m_cfg.allocation_width) {
    ++m_allocation_width_limited_events;
    return {io_access_kind::NO_FREE_LINE, {}};
  }

  tag_entry *victim = select_victim(line);
  int free_id = find_free_physical();
  const bool can_reclaim_victim =
      victim->valid && m_phys[victim->physical.id].ref_count == 0;
  if (free_id < 0 && !can_reclaim_victim) {
    ++m_no_free_physical_events;
    return {io_access_kind::NO_FREE_LINE, {}};
  }
  if (victim->valid) {
    physical_line &old = m_phys[victim->physical.id];
    assert(old.allocated && old.tag_valid);
    old.tag_valid = false;
    if (m_cfg.finite_service) m_service_map_loss[victim->physical.id] = cycle;
    ++m_tag_evictions;
    if (old.ref_count == 0) {
      release(victim->physical);
      ++m_immediate_reclaims;
    } else {
      ++m_deferred_reclaims;
    }
  }
  if (free_id < 0) free_id = find_free_physical();
  assert(free_id >= 0);
  physical_line &physical = m_phys[free_id];
  physical.allocated = true;
  physical.ready = false;
  if (m_cfg.progressive_wakeup) {
    physical.data_ready = false;
    physical.return_cycle = UINT64_MAX;
    physical.first_notify_cycle = physical.last_notify_cycle = UINT64_MAX;
    physical.notified = physical.late_merges = 0;
  }
  physical.tag_valid = true;
  physical.ref_count = 0;
  physical.waiters.clear();
  physical_identity identity{static_cast<unsigned>(free_id),
                             ++physical.generation};
  *victim = {true, line, identity, ++m_lru_clock};
  attach_reference(*owner, identity);
  ++m_allocations_this_cycle;
  ++m_new_misses;
  assert_shadow_refs();
  return {io_access_kind::NEW_MISS, identity};
}

void complete(physical_identity identity) {
  assert(fill_identity_matches(identity) &&
         "OO fill must match the original physical generation");
  physical_line &physical = m_phys[identity.id];
  assert(!physical.ready && "OO fill must wake each waiter exactly once");
  if (m_cfg.finite_service) {
    assert(m_service_cycle != UINT64_MAX);
    for (const auto &pending : m_service_returns)
      assert(pending.physical.id != identity.id ||
             pending.physical.generation != identity.generation);
    if (m_cfg.progressive_wakeup) physical.return_cycle = m_service_cycle;
    m_service_returns.push_back({identity, m_service_cycle + 1, 0});
    return;
  }
  physical.ready = true;
  for (const waiter &waiting : physical.waiters) {
    entry *owner = find_entry_by_slot(waiting.slot, waiting.slot_generation);
    assert(owner && has_reference(*owner, identity) &&
           "stale fill cannot wake a reused OO PIB slot");
    assert(owner->pending_dependencies);
    --owner->pending_dependencies;
    ++m_wakeups;
  }
  physical.waiters.clear();
  assert_shadow_refs();
}

// ready retains its X2 meaning: broadcast finished. AD's data_ready is
// exposed only at this unchanged +1 metadata edge. Unnotified consumers
// still own a pending dependency even when the data itself is available.
void advance_service(uint64_t cycle) {
  if (!m_cfg.finite_service || cycle == m_service_cycle) return;
  m_service_cycle = cycle;
  unsigned budget = 4;
  while (!m_service_returns.empty() &&
         m_service_returns.front().ready_cycle <= cycle) {
    auto &pending = m_service_returns.front();
    assert(fill_identity_matches(pending.physical));
    auto &physical = m_phys[pending.physical.id];
    if (m_cfg.progressive_wakeup) physical.data_ready = true;
    while (budget && pending.next_waiter < physical.waiters.size()) {
      const auto &waiting = physical.waiters[pending.next_waiter++];
      entry *owner = find_entry_by_slot(waiting.slot, waiting.slot_generation);
      assert(owner && has_reference(*owner, pending.physical));
      assert(owner->pending_dependencies);
      --owner->pending_dependencies;
      if (m_cfg.progressive_wakeup) {
        if (!physical.notified) physical.first_notify_cycle = cycle;
        physical.last_notify_cycle = cycle;
        ++physical.notified;
      }
      ++m_wakeups;
      --budget;
    }
    if (pending.next_waiter != physical.waiters.size()) {
      if (m_cfg.progressive_wakeup && pending.next_waiter) {
        // Early retirement allows slot reuse and arbitrarily long merge
        // streams. Discard only the consumed prefix; the live cursor still
        // names the same physical generation and unnotified slot suffix.
        physical.waiters.erase(physical.waiters.begin(),
                              physical.waiters.begin() + pending.next_waiter);
        pending.next_waiter = 0;
      }
      break;
    }
    if (m_cfg.progressive_wakeup) {
      ++m_broadcasts_finished;
      ++m_fanout_hist[std::min<uint64_t>(32, physical.notified)];
      m_first_notify_sum += physical.first_notify_cycle;
      m_last_notify_sum += physical.last_notify_cycle;
      m_broadcast_span_sum += physical.last_notify_cycle - physical.first_notify_cycle;
    }
    physical.ready = true;
    physical.waiters.clear();
    m_service_returns.pop_front();

bool retire_one_ready(uint64_t cycle, uint64_t *retired_uid = nullptr) {
  if (cycle == m_retire_cycle) return false;  // frozen width: one/cycle
  auto selected = m_entries.end();
  for (auto it = m_entries.begin(); it != m_entries.end(); ++it) {
    if (entry_ready(*it)) {
      selected = it;
      break;
    }
  }
  if (selected == m_entries.end()) return false;
  bool older_unready = false;
  for (auto it = m_entries.begin(); it != selected; ++it)
    older_unready |= !entry_ready(*it);
  if (older_unready) ++m_out_of_order_retires;
  for (const physical_identity identity : selected->references) {
    physical_line &physical = m_phys[identity.id];
    assert(physical.allocated && physical.generation == identity.generation &&
           physical.ref_count);
    --physical.ref_count;
    if (!physical.tag_valid && physical.ref_count == 0) {
      release(identity);
      ++m_final_ref_reclaims;
    }
  }
  m_slots[selected->slot].active = false;
  if (retired_uid) *retired_uid = selected->uid;
  m_entries.erase(selected);
  m_retire_cycle = cycle;
  ++m_retires;
  assert_shadow_refs();
  return true;

// Absolute core-cycle quota; checking availability never consumes a grant.
// Commit only after the owning operation actually succeeds.
class service_quota {
 public:
  explicit service_quota(unsigned width = 1) : m_width(width) { assert(width); }
  bool available(uint64_t cycle) const {
    return cycle != m_cycle || m_used < m_width;
  }
  void commit(uint64_t cycle) {
    assert(available(cycle));
    if (cycle != m_cycle) { m_cycle = cycle; m_used = 0; }
    ++m_used;
  }
 private:
  unsigned m_width;
  unsigned m_used = 0;
  uint64_t m_cycle = UINT64_MAX;
};

struct service_entry {
  // AD common boundary: first LDST observation with admission complete and
  // all real whole-line returns accepted. Independent of notification gating.
  uint64_t admitted_returns_cycle = UINT64_MAX;
  uint64_t tag_grant_cycle = UINT64_MAX;
  uint64_t ready_cycle = UINT64_MAX;
  uint64_t collect_done_cycle = UINT64_MAX;
  uint64_t collect_start_cycle = UINT64_MAX;
  unsigned sectors_left = 0;
  bool tag_can_commit(uint64_t cycle) const {
    return tag_grant_cycle != UINT64_MAX && cycle > tag_grant_cycle;
  }
  template <class Frontend>
  void prefetch_next_tag(Frontend &frontend, uint64_t cycle, bool has_next,
                         uint64_t next_address) {
    tag_grant_cycle = UINT64_MAX;
    if (has_next && frontend.try_serve_tag(cycle, next_address))
      tag_grant_cycle = cycle;
  }
  void observe_ready(uint64_t cycle, unsigned sectors) {
    assert(ready_cycle == UINT64_MAX && sectors);
    ready_cycle = cycle;
    sectors_left = sectors;
  }
  bool collect(uint64_t cycle, service_quota &port) {
    assert(ready_cycle != UINT64_MAX);
    if (cycle == ready_cycle) return false;
    while (sectors_left && port.available(cycle)) {
      if (collect_start_cycle == UINT64_MAX) collect_start_cycle = cycle;
      port.commit(cycle);
      --sectors_left;
      if (!sectors_left) collect_done_cycle = cycle;
    }
    return !sectors_left && cycle > collect_done_cycle;
  }
};

void attach_reference(entry &owner, physical_identity identity) {
  if (has_reference(owner, identity)) return;
  physical_line &physical = m_phys[identity.id];
  assert(physical.allocated && physical.generation == identity.generation);
  const uint64_t max_ref_count = (1ULL << m_cfg.ref_count_bits) - 1;
  assert(physical.ref_count < max_ref_count);
  ++physical.ref_count;
  owner.references.push_back(identity);
  if (!physical.ready) {
    if (m_cfg.progressive_wakeup && physical.data_ready) {
      ++physical.late_merges;
      ++m_late_merges;
    }
    physical.waiters.push_back({owner.slot, owner.slot_generation});
    ++owner.pending_dependencies;
  }
}
bool entry_ready(const entry &owner) const {
  if (owner.pending_dependencies || owner.external_dependencies) return false;
  for (const physical_identity identity : owner.references)
    if (!fill_identity_matches(identity) ||
        !(m_cfg.progressive_wakeup ? m_phys[identity.id].data_ready
                                  : m_phys[identity.id].ready))
      return false;
  return true;

bool ldst_unit::dtc_l1_oo_select_ready(uint64_t *uid) const {
  for (auto candidate = m_dtc_l1_oo_pib.begin();
       candidate != m_dtc_l1_oo_pib.end(); ++candidate) {
    if (candidate->operation == dtc_l1_m4_operation::CACHEABLE_LOAD &&
        candidate->next_reference != candidate->references.size())
      continue;
    const uint64_t candidate_uid = candidate->inst.get_uid();
    const bool ready = dtc_l1_sector_oo_active()
                           ? m_dtc_l1_sector_frontend->entry_ready_for(candidate_uid)
                           : m_dtc_l1_oo_frontend->entry_ready_for(candidate_uid);
    if (!ready) continue;
    bool older_same_warp_fence = false;
    for (auto older = m_dtc_l1_oo_pib.begin(); older != candidate; ++older) {
      if (older->inst.warp_id() == candidate->inst.warp_id() &&
          older->operation == dtc_l1_m4_operation::PROXY_FENCE) {
        older_same_warp_fence = true;
        break;
      }
    }
    if (!older_same_warp_fence) {
      if (uid) *uid = candidate_uid;
      return true;
    }

// Modern sector mode can enqueue up to four candidates for one logical
// reference.  Reserve that maximum before frontend mutation so its
// bounded candidate queue cannot overflow after allocation.
const size_t lower_candidate_reservation =
    dtc_l1_sector_oo_active()
        ? m_dtc_l1_sector_frontend->prospective_new_requests(
              reference.line_address, reference.sector_mask)
        : (m_dtc_l1_oo_frontend->will_new_miss(reference.line_address)
               ? 1
               : 0);
if (m_dtc_l1_oo_lower_create_queue.size() +
        lower_candidate_reservation >
    m_config->dtc_l1_oo_pib_entries) {
  ++m_dtc_l1_oo_lower_create_queue_full_stalls;
  stall_reason = BK_CONF;
  access_type = G_MEM_LD;
  return false;
}
const bool prior_grant = dtc_l1_finite_service_active() &&
                        entry->service.tag_grant_cycle != UINT64_MAX;
const bool tag_served = prior_grant || (dtc_l1_sector_oo_active()
                            ? m_dtc_l1_sector_frontend->try_serve_tag(
                                  cycle, reference.line_address)
                            : m_dtc_l1_oo_frontend->try_serve_tag(
                                  cycle, reference.line_address));
if (!tag_served) {
  stall_reason = BK_CONF;
  access_type = G_MEM_LD;
  return false;
}
if (dtc_l1_finite_service_active() &&
    (!prior_grant || !entry->service.tag_can_commit(cycle))) {
  if (!prior_grant) entry->service.tag_grant_cycle = cycle;
  stall_reason = COAL_STALL;
  access_type = G_MEM_LD;
  return false;
}
if (dtc_l1_sector_oo_active()) {
  const dtc_l1::sector_oo_frontend::access_result result =
      m_dtc_l1_sector_frontend->access(cycle, uid, reference.line_address,
                                        reference.sector_mask);
  if (result.kind == dtc_l1::io_access_kind::NO_FREE_LINE) {
    stall_reason = BK_CONF;
    access_type = G_MEM_LD;
    return false;
  }
  for (unsigned sector = 0; sector < dtc_l1::kSectorsPerLogicalLine;
       ++sector) {
    const uint8_t sector_bit = static_cast<uint8_t>(1U << sector);
    if (!(result.new_request_mask & sector_bit)) continue;
    assert(m_dtc_l1_oo_lower_create_queue.size() <
           m_config->dtc_l1_oo_pib_entries);
    m_dtc_l1_oo_lower_create_queue.push_back(
        {uid, result.physical, reference.line_address, sector_bit});
  }
} else {
  const dtc_l1::io_access_result result =
      m_dtc_l1_oo_frontend->access(cycle, uid, reference.line_address);
  if (result.kind == dtc_l1::io_access_kind::NO_FREE_LINE) {
    stall_reason = BK_CONF;
    access_type = G_MEM_LD;
    return false;
  }
  if (result.kind == dtc_l1::io_access_kind::NEW_MISS) {
    assert(m_dtc_l1_oo_lower_create_queue.size() <
           m_config->dtc_l1_oo_pib_entries);
    m_dtc_l1_oo_lower_create_queue.push_back(
        {uid, result.physical, reference.line_address, 0xF});
  }

void ldst_unit::dtc_l1_oo_issue_lower_requests() {
  if (!dtc_l1_paper_oo_active()) return;
  const unsigned long long cycle =
      m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
  if (!m_dtc_l1_oo_lower_create_queue.empty() &&
      (!dtc_l1_finite_service_active() || m_dtc_service_create.available(cycle)) &&
      m_core->get_gpu()->dtc_l1_try_acquire_lower_request()) {
    if (dtc_l1_finite_service_active()) m_dtc_service_create.commit(cycle);
    const dtc_l1_oo_lower_candidate candidate =
        m_dtc_l1_oo_lower_create_queue.front();
    dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(candidate.inst_uid);
    assert(entry);
    mem_access_byte_mask_t byte_mask;
    mem_access_sector_mask_t sector_mask;
    uint64_t request_address = candidate.line_address;
    unsigned request_size = dtc_l1::kLogicalLineBytes;
    if (dtc_l1_sector_oo_active()) {
      assert(candidate.sector_mask && !(candidate.sector_mask &
                                         (candidate.sector_mask - 1)) &&
             !(candidate.sector_mask & ~0xFU));
      unsigned sector = 0;
      while (!(candidate.sector_mask & (1U << sector))) ++sector;
      request_address += sector * 32;
      request_size = 32;
      sector_mask.set(sector);
      for (unsigned byte = sector * 32; byte < (sector + 1) * 32; ++byte)
        byte_mask.set(byte);
    } else {
      byte_mask.set();
      sector_mask.set();
    }
    mem_access_t lower_read(GLOBAL_ACC_R, request_address, request_size, false,
                            entry->inst.get_warp_active_mask(), byte_mask,
                            sector_mask, m_memory_config->gpgpu_ctx);
    mem_fetch *mf = m_mf_allocator->alloc(entry->inst, lower_read, cycle);
    const bool inserted = m_dtc_l1_oo_inflight
                              .emplace(mf->get_request_uid(),
                                       dtc_l1_oo_inflight{candidate.physical,
                                                           candidate.line_address,
                                                           candidate.inst_uid,
                                                           candidate.sector_mask})
                              .second;
    assert(inserted && "OO request UID must remain unique while live");
    m_dtc_l1_oo_lower_issue_queue.push_back(mf);
    m_dtc_l1_oo_lower_create_queue.pop_front();
    ++m_dtc_l1_oo_lower_created;
  }
  // Frozen lower issue width: one request per SM/cycle.
  if (!m_dtc_l1_oo_lower_issue_queue.empty()) {
    mem_fetch *mf = m_dtc_l1_oo_lower_issue_queue.front();
    if ((!dtc_l1_finite_service_active() || m_dtc_service_inject.available(cycle)) &&
        !m_icnt->full(mf->size(), false)) {
      if (dtc_l1_finite_service_active()) m_dtc_service_inject.commit(cycle);
      mf->set_status(IN_ICNT_TO_MEM, cycle);
      m_icnt->push(mf);
      m_dtc_l1_oo_lower_issue_queue.pop_front();
      ++m_dtc_l1_oo_lower_issued;
    }

bool ldst_unit::dtc_l1_oo_writeback_ready() {
  const uint64_t service_cycle = m_core->get_gpu()->global_cycle();
  if (dtc_l1_finite_service_active() &&
      !m_dtc_service_retire.available(service_cycle)) return false;
  if (!dtc_l1_paper_oo_active()) return false;
  uint64_t uid = 0;
  const bool ready = dtc_l1_oo_select_ready(&uid);
  if (!ready) return false;
  dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(static_cast<unsigned>(uid));
  assert(entry);
  const unsigned long long cycle =
      m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
  if (entry->operation != dtc_l1_m4_operation::CACHEABLE_LOAD) {
    assert(entry->source_completed && entry->references.empty());
    const bool retired_ok = dtc_l1_sector_oo_active()
                                ? m_dtc_l1_sector_frontend->retire_ready_uid(
                                      cycle, uid)
                                : m_dtc_l1_oo_frontend->retire_ready_uid(cycle,
                                                                         uid);
    assert(retired_ok);
    if (dtc_l1_finite_service_active()) m_dtc_service_retire.commit(service_cycle);
    for (auto it = m_dtc_l1_oo_pib.begin(); it != m_dtc_l1_oo_pib.end(); ++it)
      if (it->inst.get_uid() == uid) {
        m_dtc_l1_oo_pib.erase(it);
        break;
      }
    ++m_dtc_l1_m4_observation_retires;
    m_dtc_l1_oo_out_of_order_retires =
        dtc_l1_sector_oo_active()
            ? m_dtc_l1_sector_frontend->out_of_order_retires()
            : m_dtc_l1_oo_frontend->out_of_order_retires();
    return true;
  }
  if (!dtc_l1_service_collect(entry->service, entry->references)) return false;
  m_next_wb = entry->inst;
  if (!m_operand_collector->writeback(m_next_wb)) {
    ++m_dtc_l1_oo_ready_but_wb_blocked_cycles;
    m_next_wb.clear();
    return false;
  }
  // Mirror IO: readiness becomes a non-retryable ledger transition only on
  // the successful shared-operand-collector grant.
  dtc_l1_r4c1_record_ready(entry->inst,
                            static_cast<unsigned>(entry->next_reference),
                            static_cast<unsigned>(entry->references.size()), "OO");
  const unsigned dependencies =
      dtc_l1_r4c3_registered_dependencies(entry->inst);
  dtc_l1_service_retired(entry->service);
  dtc_l1_oo_complete_instruction(entry->inst, dependencies);
  uint64_t retired = 0;
  const bool retired_ok = dtc_l1_sector_oo_active()
                              ? m_dtc_l1_sector_frontend->retire_ready_uid(
                                    cycle, uid)
                              : m_dtc_l1_oo_frontend->retire_ready_uid(cycle,
                                                                       uid);
  assert(retired_ok);
  for (auto it = m_dtc_l1_oo_pib.begin(); it != m_dtc_l1_oo_pib.end(); ++it) {
    if (it->inst.get_uid() == uid) {
      m_dtc_l1_oo_pib.erase(it);
      break;
    }
  }
  m_dtc_l1_oo_out_of_order_retires =
      dtc_l1_sector_oo_active()
          ? m_dtc_l1_sector_frontend->out_of_order_retires()
          : m_dtc_l1_oo_frontend->out_of_order_retires();
  m_next_wb.clear();

std::deque<mem_fetch *> m_next_global;
dtc_l1::service_quota m_dtc_service_refill;
dtc_l1::service_quota m_dtc_service_create;
dtc_l1::service_quota m_dtc_service_inject;
dtc_l1::service_quota m_dtc_service_retire;
dtc_l1::service_quota m_dtc_service_collect{4};

dtc_config.pib_entries = m_config->dtc_l1_pib_entries;
dtc_config.tag_banks = m_config->dtc_l1_tag_banks;
dtc_config.tag_requests_per_bank_per_cycle =
    m_config->dtc_l1_tag_requests_per_bank_per_cycle;
dtc_config.tag_requests_per_cycle =
    m_config->dtc_l1_tag_requests_per_cycle;
dtc_config.logical_sets = m_config->dtc_l1_logical_sets;
dtc_config.logical_ways = m_config->dtc_l1_logical_ways;
dtc_config.physical_lines = m_config->dtc_l1_physical_lines;
dtc_config.allocation_width = m_config->dtc_l1_allocation_width;
dtc_config.io_pib_entries = m_config->dtc_l1_io_pib_entries;
dtc_config.oo_pib_entries = m_config->dtc_l1_oo_pib_entries;
dtc_config.ref_count_bits = m_config->dtc_l1_ref_count_bits;
m_dtc_l1_frontend = std::make_unique<dtc_l1::paper_frontend>(dtc_config);
if (m_config->dtc_l1_mode == static_cast<unsigned>(dtc_l1::mode::PAPER_IO))
  m_dtc_l1_io_frontend = std::make_unique<dtc_l1::io_frontend>(dtc_config);
